import 'package:flutter/material.dart';

class AppButton extends StatelessWidget { const AppButton({super.key, required this.label, required this.onPressed, this.icon}); final String label; final VoidCallback? onPressed; final IconData? icon; @override Widget build(BuildContext context) => FilledButton.icon(onPressed: onPressed, icon: Icon(icon ?? Icons.arrow_back), label: Text(label), style: FilledButton.styleFrom(minimumSize: const Size.fromHeight(52))); }
class EmptyStateWidget extends StatelessWidget { const EmptyStateWidget({super.key, required this.title, required this.description, required this.icon}); final String title; final String description; final IconData icon; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, children: <Widget>[Icon(icon, size: 58), const SizedBox(height: 12), Text(title, style: Theme.of(context).textTheme.titleLarge), Text(description, textAlign: TextAlign.center)]))); }
class LoadingStateWidget extends StatelessWidget { const LoadingStateWidget({super.key}); @override Widget build(BuildContext context) => const Center(child: CircularProgressIndicator()); }
class ErrorStateWidget extends StatelessWidget { const ErrorStateWidget({super.key, required this.onRetry}); final VoidCallback onRetry; @override Widget build(BuildContext context) => Center(child: FilledButton(onPressed: onRetry, child: const Text('إعادة المحاولة'))); }
